# Composite Check. Options, results and panel: jamovi/compositeCheck.*.yaml
# (generated by tools/gen_yaml.py); jmvtools generates R/compositeCheck.h.R.
# The statistics are in compositeWiz() (R/engine-composite.R). The analysis is
# quick (no iterative model fitting), so it has no Run checkbox.

compositeCheckClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "compositeCheckClass",
  inherit = compositeCheckBase,
  private = list(
    .run = function() {
      opt <- self$options
      out <- self$results
      if (length(opt$indicators) < 2L || length(opt$outcomes) < 2L) {
        psw_jmv_todo(out$todo, c(
          "Choose at least two formative indicators and at least two outcome variables.",
          paste0("The question answered: do the indicators relate to the outcomes through ONE composite? ",
                 "With a single outcome any set of indicators passes, so two or more outcomes are required.")))
        return(invisible())
      }
      res <- tryCatch(compositeWiz(self$data, opt$indicators, opt$outcomes, folds = opt$folds, repeats = opt$repeats),
                      error = function(e) jmvcore::reject(conditionMessage(e), code = ""))
      psw_jmv_todo(out$todo, psw_jmv_escape(res$summary), res$notes)

      t <- res$test
      psw_jmv_fill(out$test, list(list(chisq = t$chisq, df = t$df, p = t$p, rho1 = t$rho1, rho2 = t$rho2)))
      out$test$setNote("what", paste0(
        "Null hypothesis: every indicator's effects on the different outcomes are proportional, i.e. the ",
        "indicators act through a single composite (Franke, Preacher & Rigdon, 2008). Tested as a rank-one ",
        "restriction with Bartlett's test on the second and later canonical correlations. ",
        sprintf("N = %d.", res$info$n)), init = FALSE)

      r <- res$r2
      psw_jmv_fill(out$r2, lapply(seq_len(nrow(r)), function(i)
        list(outcome = r$outcome[i], free = r$free[i], composite = r$composite[i], unit = r$unit[i],
             retained = r$retained[i], cvFree = r$cv.free[i], cvComposite = r$cv.composite[i], cvUnit = r$cv.unit[i])))
      out$r2$setNote("what", sprintf(paste0(
        "Separate weights: each outcome regressed on all indicators. One composite: a single set of estimated ",
        "weights for all outcomes. Unit-weighted sum: the sum of the standardized indicators. In sample, separate ",
        "weights always fit best; the cross-validated values (%d folds, %d repetitions) show what generalises. ",
        "A negative cross-validated R\u00B2 means worse than predicting the mean."),
        res$info$folds, res$info$repeats), init = FALSE)

      w <- res$weights
      psw_jmv_fill(out$weights, lapply(seq_len(nrow(w)), function(i) as.list(w[i, , drop = FALSE])))
      out$weights$setNote("what", paste0(
        "Weights apply to standardized indicators and give a composite with unit variance. ",
        "VIF above about 5 means the indicator is nearly redundant with the others and its weight is unstable."),
        init = FALSE)
      invisible()
    }
  )
)
